"""Storage interface. Local encrypted disk today; an S3-compatible backend later (Phase 14)."""

import re
import uuid
from dataclasses import dataclass
from typing import Protocol

# Object keys are generated by the platform, never taken from user input.
OBJECT_KEY_RE = re.compile(r"^[0-9a-f]{32}$")


class StorageError(Exception):
    pass


@dataclass(frozen=True)
class StoredObject:
    key: str
    sha256: str  # of the plaintext
    size_bytes: int  # of the plaintext


def new_object_key() -> str:
    return uuid.uuid4().hex


def validate_object_key(key: str) -> str:
    if not OBJECT_KEY_RE.fullmatch(key):
        raise StorageError("Invalid object key")
    return key


class ObjectStorage(Protocol):
    def put(self, data: bytes) -> StoredObject: ...

    def get(self, key: str) -> bytes: ...

    def delete(self, key: str) -> None: ...

    def exists(self, key: str) -> bool: ...
